    #Node Combine Color
    @classmethod
    def combine_color(
        cls,
        red: Float=None,
        hue: Float=None,
        green: Float=None,
        saturation: Float=None,
        blue: Float=None,
        lightness: Float=None,
        value: Float=None,
        alpha: Float=None,
        mode: T_MODE_3='RGB'):
        """Node Combine Color.
        
        Jump: False

        Parameters
        ----------
        red : Float, optional
            Socket 'Red', identifier 'Red' (default: None)
        hue : Float, optional
            Socket 'Hue', identifier 'Red' (default: None)
        green : Float, optional
            Socket 'Green', identifier 'Green' (default: None)
        saturation : Float, optional
            Socket 'Saturation', identifier 'Green' (default: None)
        blue : Float, optional
            Socket 'Blue', identifier 'Blue' (default: None)
        lightness : Float, optional
            Socket 'Lightness', identifier 'Blue' (default: None)
        value : Float, optional
            Socket 'Value', identifier 'Blue' (default: None)
        alpha : Float, optional
            Socket 'Alpha' (default: None)
        mode : {'RGB', 'HSV', 'HSL'}, optional
            Node parameter 'mode' (default: 'RGB')

        Returns
        -------
        Socket
            Default output socket.
        """
        named_sockets = {'ID_Red': None, 'ID_Green': None, 'ID_Blue': None, 'ID_Alpha': alpha}
        named_sockets['ID_Red'] = None
        if red is not None: named_sockets['ID_Red'] = red
        if hue is not None: named_sockets['ID_Red'] = hue
        named_sockets['ID_Green'] = None
        if green is not None: named_sockets['ID_Green'] = green
        if saturation is not None: named_sockets['ID_Green'] = saturation
        named_sockets['ID_Blue'] = None
        if blue is not None: named_sockets['ID_Blue'] = blue
        if lightness is not None: named_sockets['ID_Blue'] = lightness
        if value is not None: named_sockets['ID_Blue'] = value

        node = Node( 'Combine Color', named_sockets=named_sockets, mode=mode)
        return node._out

