    #Node Integer Math
    @classmethod
    def integer_math(
        cls,
        value: Integer=None,
        base: Integer=None,
        value_1: Integer=None,
        exponent: Integer=None,
        multiplier: Integer=None,
        addend: Integer=None,
        operation: T_OPERATION_4='ADD'):
        """Node Integer Math.
        
        Jump: False

        Parameters
        ----------
        value : Integer, optional
            Socket 'Value', identifier 'Value' (default: None)
        base : Integer, optional
            Socket 'Base', identifier 'Value' (default: None)
        value_1 : Integer, optional
            Socket 'Value', identifier 'Value_001' (default: None)
        exponent : Integer, optional
            Socket 'Exponent', identifier 'Value_001' (default: None)
        multiplier : Integer, optional
            Socket 'Multiplier', identifier 'Value_001' (default: None)
        addend : Integer, optional
            Socket 'Addend' (default: None)
        operation : {'ADD', 'SUBTRACT', 'MULTIPLY', 'DIVIDE', 'MULTIPLY_ADD', 'ABSOLUTE', 'NEGATE', 'POWER', 'MINIMUM', 'MAXIMUM', 'SIGN', 'DIVIDE_ROUND', 'DIVIDE_FLOOR', 'DIVIDE_CEIL', 'FLOORED_MODULO', 'MODULO', 'GCD', 'LCM'}, optional
            Node parameter 'operation' (default: 'ADD')

        Returns
        -------
        Socket
            Default output socket.
        """
        named_sockets = {'ID_Value': None, 'ID_Value_001': None, 'ID_Value_002': addend}
        named_sockets['ID_Value'] = None
        if value is not None: named_sockets['ID_Value'] = value
        if base is not None: named_sockets['ID_Value'] = base
        named_sockets['ID_Value_001'] = None
        if value_1 is not None: named_sockets['ID_Value_001'] = value_1
        if exponent is not None: named_sockets['ID_Value_001'] = exponent
        if multiplier is not None: named_sockets['ID_Value_001'] = multiplier

        node = Node( 'Integer Math', named_sockets=named_sockets, operation=operation)
        return node._out

